#include "Msg28346Router.h"

#include <algorithm>
#include <limits>
#include <new>
#include <sstream>
#include <utility>

namespace
{
	constexpr size_t kOfficial28346HeaderLen = 0x0C;

	static USHORT ReadBE16(const BYTE* p)
	{
		return static_cast<USHORT>((static_cast<USHORT>(p[0]) << 8) | static_cast<USHORT>(p[1]));
	}

	static UINT ReadBE32(const BYTE* p)
	{
		return (static_cast<UINT>(p[0]) << 24) |
			(static_cast<UINT>(p[1]) << 16) |
			(static_cast<UINT>(p[2]) << 8) |
			static_cast<UINT>(p[3]);
	}

	static void FillDiag(
		Msg28346ParseDiag* diag,
		const char* reason,
		size_t bodyLen,
		const Msg28346Envelope& env)
	{
		if (!diag)
		{
			return;
		}
		diag->ParseMode = "official-28346-be";
		diag->Reason = reason ? reason : "";
		diag->BodyLen = bodyLen;
		diag->HeaderLen = env.HeaderLen;
		diag->OuterUin = env.OuterUin;
		diag->Context = env.Context;
		diag->InnerMsg = env.InnerMsg;
		diag->InnerLen = env.InnerLen;
		diag->Mode = env.Mode;
	}
}

bool TryParseOfficialMsg28346Envelope(
	const BYTE* body,
	size_t bodyLen,
	USHORT expectedInnerMsg,
	Msg28346Envelope& out,
	Msg28346ParseDiag* diag)
{
	out = Msg28346Envelope{};
	out.HeaderLen = kOfficial28346HeaderLen;

	if (!body)
	{
		FillDiag(diag, "body null", bodyLen, out);
		return false;
	}
	if (bodyLen < kOfficial28346HeaderLen + 1)
	{
		FillDiag(diag, "body too short", bodyLen, out);
		return false;
	}

	out.OuterUin = ReadBE32(body + 0x00);
	out.Context = ReadBE32(body + 0x04);
	out.InnerMsg = ReadBE16(body + 0x08);
	out.InnerLen = ReadBE16(body + 0x0A);
	out.InnerBody = body + kOfficial28346HeaderLen;
	out.InnerBodyLen = bodyLen - kOfficial28346HeaderLen;

	if (out.OuterUin == 0)
	{
		FillDiag(diag, "outer uin zero", bodyLen, out);
		return false;
	}
	if (out.Context != 0)
	{
		FillDiag(diag, "context is not zero", bodyLen, out);
		return false;
	}
	if (expectedInnerMsg != 0 && out.InnerMsg != expectedInnerMsg)
	{
		FillDiag(diag, "inner msg mismatch", bodyLen, out);
		return false;
	}
	if (out.InnerLen == 0)
	{
		FillDiag(diag, "inner length zero", bodyLen, out);
		return false;
	}

	const size_t expectedBodyLen = kOfficial28346HeaderLen + static_cast<size_t>(out.InnerLen) + 1;
	if (expectedBodyLen != bodyLen)
	{
		FillDiag(diag, "envelope length mismatch", bodyLen, out);
		return false;
	}

	out.Mode = body[expectedBodyLen - 1];
	if (out.Mode != 1)
	{
		FillDiag(diag, "mode is not one", bodyLen, out);
		return false;
	}

	out.InnerBodyLen = out.InnerLen;
	FillDiag(diag, "ok", bodyLen, out);
	return true;
}

