        const Byte v102 = Ror8(Ror8(QQSpeedCSSafe::kC30[stored ^ 0x6Du], 4), 7);
        return QQSpeedCSSafe::kB30[Rol8(Ror8(v102, 1), 4)] ^ 0x6Du;
