    bool DecodeP2P(Reader& r, ObjectWriter& o)
    {
        if (!ReadPutVar(r, o, T::kNestedVarP2pRaceBeginTime, 32, 39035, "p2p.race_begin_time") ||
            !ReadPutVar(r, o, T::kNestedVarP2pUin, 32, 12347, "p2p.uin") ||
            !ReadPutVar(r, o, T::kNestedVarP2pLagCount, 32, 39039, "p2p.lag_count") ||
            !ReadPutByte(r, o, T::kNestedByteP2pServerUdpLoginStatus, 12351, "p2p.server_udp_login_status") ||
            !r.ReadPadding(T::kNestedPaddingP2pRecordHead, 0x0B, "p2p.record_head"))
            return false;

        std::uint32_t playerCount = 0;
        if (!ReadPutCount(r, o, T::kNestedCountP2pPlayerNum, 8, 12352, 20,
                "p2p.player_num", playerCount))
            return false;
        for (std::uint32_t playerIndex = 0; playerIndex < playerCount; ++playerIndex)
        {
            const std::size_t base = 12353 + static_cast<std::size_t>(playerIndex) * 1284;
            if (!ReadPutVar(r, o, T::kNestedVarP2pPlayerNotPassStateCount, 32,
                    base + 14, "p2p.player.not_pass_state_count"))
                return false;

            std::uint32_t detailCount = 0;
            if (!ReadPutCount(r, o, T::kNestedCountP2pDetailNum, 8, base + 1256,
                    3, "p2p.player.detail_num", detailCount))
                return false;
            for (std::uint32_t detailIndex = 0; detailIndex < detailCount; ++detailIndex)
            {
                const std::size_t detailBase = base + 1257 + static_cast<std::size_t>(detailIndex) * 9;
                if (!ReadPutVar(r, o, T::kNestedVarP2pDetailCountValue, 32,
                        detailBase + 5, "p2p.detail.count") ||
                    !ReadPutByte(r, o, T::kNestedByteP2pDetailType,
                        detailBase, "p2p.detail.type") ||
                    !ReadPutVar(r, o, T::kNestedVarP2pDetailMsgId, 32,
                        detailBase + 1, "p2p.detail.msg_id") ||
                    !r.ReadPadding(T::kNestedPaddingP2pDetail, 0xB6, "p2p.detail.padding"))
                    return false;
            }

            for (std::size_t index = 0; index < 3; ++index)
            {
                if (!ReadPutVar(r, o, T::kNestedVarP2pPlayerSendDataCount, 32,
                        base + 18 + index * 4, "p2p.player.send_data_count"))
                    return false;
            }
            if (!ReadPutVar(r, o, T::kNestedVarP2pPlayerP2pNetSpeed, 32,
                    base + 6, "p2p.player.p2p_net_speed") ||
                !ReadPutVar(r, o, T::kNestedVarP2pPlayerUin, 32,
                    base, "p2p.player.uin") ||
                !ReadPutByte(r, o, T::kNestedByteP2pPlayerConnectState,
                    base + 4, "p2p.player.connect_state"))
                return false;
            for (std::size_t index = 0; index < 3; ++index)
            {
                if (!ReadPutVar(r, o, T::kNestedVarP2pPlayerRecvDataCount, 32,
                        base + 30 + index * 4, "p2p.player.recv_data_count"))
                    return false;
            }
            if (!ReadPutVar(r, o, T::kNestedVarP2pPlayerNetSpeed, 32,
                    base + 10, "p2p.player.net_speed") ||
                !ReadPutByte(r, o, T::kNestedByteP2pPlayerCanPass,
                    base + 5, "p2p.player.can_pass") ||
                !r.ReadPadding(T::kNestedPaddingP2pPlayerHead, 0x01, "p2p.player.padding_head"))
                return false;

            std::uint32_t recvCount = 0;
            if (!ReadPutCount(r, o, T::kNestedCountP2pRecvPkgNum, 16, base + 54,
                    100, "p2p.player.recv_pkg_num", recvCount))
                return false;
            for (std::uint32_t recvIndex = 0; recvIndex < recvCount; ++recvIndex)
            {
                const std::size_t recvBase = base + 56 + static_cast<std::size_t>(recvIndex) * 12;
                if (!ReadPutVar(r, o, T::kNestedVarP2pRecvPkgId, 32,
                        recvBase, "p2p.recv.pkg_id") ||
                    !ReadPutVar(r, o, T::kNestedVarP2pRecvDistanceDiff, 32,
                        recvBase + 8, "p2p.recv.distance_diff") ||
                    !ReadPutVar(r, o, T::kNestedVarP2pRecvTime, 32,
                        recvBase + 4, "p2p.recv.recv_time") ||
                    !r.ReadPadding(T::kNestedPaddingP2pRecvPkg, 0xFB, "p2p.recv.padding"))
                    return false;
            }
            for (std::size_t index = 0; index < 3; ++index)
            {
                if (!ReadPutVar(r, o, T::kNestedVarP2pPlayerServerRecvDataCount, 32,
                        base + 42 + index * 4, "p2p.player.server_recv_data_count"))
                    return false;
            }
            if (!r.ReadPadding(T::kNestedPaddingP2pPlayerTail, 0x87, "p2p.player.padding_tail"))
                return false;
        }

        std::uint32_t sendCount = 0;
        if (!ReadPutCount(r, o, T::kNestedCountP2pSendPkgNum, 16, 38033, 100,
                "p2p.send_pkg_num", sendCount))
            return false;
        for (std::uint32_t index = 0; index < sendCount; ++index)
        {
            const std::size_t base = 38035 + static_cast<std::size_t>(index) * 10;
            if (!ReadPutByte(r, o, T::kNestedByteP2pSendUdpStatus,
                    base + 8, "p2p.send.udp_status") ||
                !ReadPutVar(r, o, T::kNestedVarP2pSendTime, 32,
                    base + 4, "p2p.send.send_time") ||
                !ReadPutByte(r, o, T::kNestedByteP2pSendDataMethod,
                    base + 9, "p2p.send.data_method") ||
                !ReadPutVar(r, o, T::kNestedVarP2pSendPkgId, 32,
                    base, "p2p.send.pkg_id") ||
                !r.ReadPadding(T::kNestedPaddingP2pSendPkg, 0xE3, "p2p.send.padding"))
                return false;
        }
        return
            ReadPutVar(r, o, T::kNestedVarP2pLagCountGlobal, 32, 39043, "p2p.lag_count_global") &&
            ReadPutVar(r, o, T::kNestedVarP2pTickInLevel, 32, 39047, "p2p.tick_in_level") &&
            r.ReadPadding(T::kNestedPaddingP2pRecordTail, 0x43, "p2p.record_tail");
    }

